 'd-dne':{zh:'DNE3',en:'DNE3',t:['DNE3：目录自动分片','DNE3: Automatic Directory Restriping'],lines:['d-lay'],pos:{ddn:0},tag:'ddn',lv:2,st:'live',page:'topics/d-dne/index.html',steps:5,prev:['d-exa','d-mds'],next:['d-oss','d-stripe','d-dom'],
  d:['启用自动分片后，Lustre 可按目录大小阈值增加目录条带，并把目录项分布到多个 MDT。','With auto-split enabled, Lustre can add directory stripes at configured size thresholds and distribute entries across MDTs.']},
 'd-pool':{zh:'存储池',en:'Pools',lines:['d-lay'],pos:{ddn:10},tag:'ddn',lv:1,st:'wip',hidden:true,
  d:['把数据服务器按闪存或硬盘分组，目录可以绑定到指定的池。','Data servers are grouped into flash or disk pools, and a directory can be pinned to a pool.']},
 'd-dom':{zh:'DoM 小文件',en:'Data on MDT',t:['DoM：小文件为什么要放在元数据层','Data on MDT: Why Small Files Live on the Metadata Tier'],lines:['d-lay'],pos:{ddn:3},tag:'ddn',lv:2,st:'live',page:'topics/d-dom/index.html',steps:6,prev:['d-stripe','d-mds'],next:['d-pfl','d-dne'],
  d:['小文件或文件开头直接存在元数据层的闪存上，一次来回就拿到属性和内容。','Small files, or the start of a file, sit on the metadata flash, so one round trip returns both attributes and data.']},
 'd-hotpools':{zh:'Hot Pools',en:'Hot Pools',t:['Hot Pools：闪存和硬盘在同一个目录里自动分冷热','Hot Pools: Automatic Hot/cold Placement Between Flash and Disk in One Namespace'],lines:['d-lay'],pos:{ddn:13},tag:'ddn',lv:2,st:'live',page:'topics/d-hotpools/index.html',steps:7,prev:['d-pool','d-flr','d-pfl'],next:['d-dcr','d-hotnodes','tier'],
  d:['同一个命名空间里，按文件冷热在闪存和硬盘之间自动建副本、删副本。','Within one namespace, files gain or lose flash and disk copies automatically depending on how hot they are.']},
 'd-spill':{zh:'溢出保护',en:'Spillover',lines:['d-lay'],pos:{ddn:14},tag:'ddn',lv:2,st:'wip',hidden:true,
  d:['闪存快满时，新写入临时改写到硬盘池，不会把闪存写爆。','When flash is nearly full, new writes go to the disk pool for a while instead.']},
 'd-flr':{kw:["文件级镜像","FLR","File Level Redundancy","文件级冗余"],zh:'FLR\n文件镜像',en:'File-level\nMirroring',t:['FLR 文件级镜像','FLR File-Level Mirroring'],lines:['d-lay','d-dp'],pos:{ddn:9},tag:'ddn',lv:2,st:'live',page:'topics/d-flr/index.html',steps:5,prev:['d-exa','d-stripe','d-pfl'],next:['d-hotpools','d-ha','d-dcr'],
  d:['按文件把相同内容放在不同目标上，读取时使用可用且最新的镜像。','Mirror selected files across storage targets and read from an available, up-to-date mirror.']},
 'd-pfl':{kw:["progressive file layout","PFL","Progressive File Layout","渐进式文件布局"],zh:'PFL\n渐进布局',en:'Progressive\nLayouts',t:['PFL 渐进式文件布局','PFL Progressive File Layout'],lines:['d-lay'],pos:{ddn:7},tag:'ddn',lv:2,st:'live',page:'topics/d-pfl/index.html',steps:5,prev:['d-exa','d-stripe','d-dom'],next:['d-flr','d-hotpools'],
  d:['按文件偏移把数据分成多个范围，各范围使用自己的条带规则和目标池。','Divide a file by byte offset and apply separate striping and target-pool rules to each range.']},
 'd-compress':{zh:'按池压缩',en:'Per-pool\nCompression',t:['EXAScaler 客户端压缩','EXAScaler Client-Side Compression'],lines:['d-lay'],pos:{ddn:15},tag:'ddn',lv:2,st:'live',generic:'dr',page:'topics/d-compress/index.html',steps:5,prev:['d-exa','d-stripe','dr'],next:['d-enc','d-pfl'],
  d:['EXAScaler 客户端先压缩数据再传给存储，CSI 存储类可选择压缩算法。','EXAScaler compresses data on the client before transfer, and CSI StorageClasses can select the algorithm.']},

/* ================= DDN：数据保护 ================= */
 'd-dcr':{kw:["declustered RAID"],zh:'分簇 RAID',en:'Declustered RAID',t:['分簇 RAID：坏一块盘时，让很多盘一起重建','Declustered RAID: Many Drives Rebuild Together When One Fails'],lines:['d-dp'],pos:{ddn:0},tag:'ddn',lv:2,st:'live',page:'topics/d-dcr/index.html',steps:6,generic:'ec',prev:['ec','d-exahw'],next:['gds','d-ha'],
  d:['数据、校验和备用空间打散到池里所有盘上，坏一块盘时很多盘一起重建。','Data, parity and spare space are spread over every drive in the pool, so many drives rebuild together when one fails.']},
 'd-rebuild':{zh:'重建回拷',en:'Copyback',lines:['d-dp'],pos:{ddn:4},tag:'ddn',lv:2,st:'wip',hidden:true,
  d:['换上新盘后，重建到备用空间的数据再拷回原位。','After a drive is replaced, data rebuilt into spare space is copied back.']},
 'd-enc':{zh:'客户端\n加密',en:'Client-side\nEncryption',t:['EXAScaler 客户端加密','EXAScaler Client-Side Encryption'],lines:['d-dp'],pos:{ddn:15},tag:'ddn',lv:2,st:'live',page:'topics/d-enc/index.html',steps:5,prev:['d-exa','d-client'],next:['d-kmip','d-compress'],
  d:['客户端在写出前加密文件内容，存储保存密文，解密使用客户端加载的密钥。','The client encrypts file contents before sending them, storage keeps ciphertext, and the client uses a loaded key to decrypt it.']},
 'd-ha':{zh:'双控与\n成对 HA',en:'Dual\nControllers',t:['EXAScaler 双控与成对高可用','Dual Controllers and Paired High Availability'],lines:['d-dp'],pos:{ddn:10},tag:'ddn',lv:1,st:'live',page:'topics/d-ha/index.html',steps:5,prev:['d-exa','d-exahw','d-oss'],next:['d-dcr','d-flr','d-exahw'],
  d:['SFA 双活控制器提供后端存储路径，成对文件系统服务器可接管同一个存储目标。','Active-active SFA controllers provide back-end storage paths, and a file service can take over the same target on its partner server.']},
 'd-kmip':{zh:'自加密盘与\nKMIP',en:'Self-encrypting\nDrives',t:['自加密盘与 KMIP：盘内加密和密钥管理','Self-Encrypting Drives and KMIP: On-Drive Encryption and Key Management'],lines:['d-dp'],pos:{ddn:16},tag:'ddn',lv:2,st:'live',page:'topics/d-kmip/index.html',steps:5,prev:['d-exahw','d-dcr'],next:['d-enc','d-csi'],
  d:['自加密盘在盘内加解密，DDN SFA 可借助外部 KMIP 服务保管盘的认证密钥。','Self-encrypting drives encrypt and decrypt data on the drive, and DDN SFA can use an external KMIP service to store drive authentication keys.']},
 'd-mt':{zh:'租户隔离',en:'Tenant Isolation',t:['EXAScaler 租户隔离','EXAScaler Tenant Isolation'],lines:['d-dp'],pos:{ddn:14},tag:'ddn',lv:2,st:'live',page:'topics/d-mt/index.html',steps:6,prev:['d-exa','d-client'],next:['d-csi','d-enc'],
  d:['按客户端节点组划分租户，每个租户只看到自己的目录和配额。','Tenants are defined by groups of client nodes, and each sees only its own directory and quota.']},

/* ================= DDN：AI 数据路径 ================= */
