 'd-kvcore':{zh:'键值底座',en:'Key-value Core',t:['Infinia 键值底座：数据、元数据与布局','Infinia’s Key-Value Engine: Data, Metadata, and Layout'],lines:['d-inf'],pos:{ddn:0},tag:'ddn',lv:2,st:'live',page:'topics/d-kvcore/index.html',steps:5,prev:['d-inf','obj'],next:['d-key','d-views','d-iec'],
  d:['将键值、数据与元数据的读取以及分布式布局放在同一个存储引擎中。','Uses one distributed engine for key-value access, data and metadata reads, and data placement.']},
 'd-key':{zh:'键与租户',en:'Keys and\nTenants',t:['Infinia 键构造与租户键空间：从片段定位到访问隔离','Infinia Key Construction and Tenant Keyspaces: From Fragment Lookup to Access Isolation'],lines:['d-inf'],pos:{ddn:5},tag:'ddn',lv:2,st:'live',page:'topics/d-key/index.html',steps:7,prev:['d-inf','d-kvcore'],next:['d-views','d-iec'],d:['Infinia 以带租户标识的键定位记录，以访问控制约束请求，并按租户分配资源。','Infinia uses tenant-scoped keys to locate records, access controls to govern requests, and policies to allocate resources across tenants.'],kw:['地址即权限','Address as Permission','Infinia 租户键空间与访问隔离','Infinia Tenant Keyspaces and Access Isolation']},
 'd-views':{zh:'协议即视图',en:'Protocols\nas Views',t:['Infinia 协议视图：S3、POSIX 与原生 KV Cache','Infinia Protocol Views: S3, POSIX, and Native KV Cache'],lines:['d-inf'],pos:{ddn:8},tag:'ddn',lv:2,st:'live',page:'topics/d-views/index.html',steps:5,prev:['d-inf','d-kvcore','obj'],next:['d-key','kvoff'],d:['S3、POSIX 和原生 KV Cache 接口各自提供应用所需的语义，底层共用一个存储引擎。','S3, POSIX, and native KV cache provide distinct application semantics on a shared storage engine.']},
 'd-iec':{zh:'客户端\n纠删码',en:'Client-side\nEC',t:['Infinia 动态纠删码：从写入到恢复','Infinia Dynamic Erasure Coding: From Write to Recovery'],lines:['d-dp'],pos:{ddn:8},tag:'ddn',lv:2,st:'live',generic:'ec',page:'topics/d-iec/index.html',steps:5,prev:['ec','d-inf'],next:['d-kvcore','d-dcr'],
  d:['根据写入特征选择数据布局和纠删码，并跨故障域放置片段。','Selects an erasure code and layout based on write characteristics and places fragments across failure domains.']},
