 'w-user':{zh:'用户态 I/O',en:'User-space I/O',t:['NeuralMesh 的用户态 I/O','User-Space I/O in NeuralMesh'],lines:['w-arch'],pos:{weka:1},tag:'weka',lv:2,st:'live',page:'topics/w-user/index.html',steps:5,prev:['w-nm','w-vfs'],next:['w-dpdk'],d:['原生 POSIX 请求经 Linux VFS 进入 WEKA 前端，用户态服务处理后续文件系统 I/O。','Native POSIX requests enter the WEKA frontend through Linux VFS, and user-space services handle subsequent file system I/O.'],kw:[]},
 'w-dpdk':{zh:'DPDK 网络',en:'DPDK\nNetworking',t:['NeuralMesh 的 DPDK 网络：独占核与共享核','DPDK Networking in NeuralMesh: Dedicated and Shared Cores'],lines:['w-arch'],pos:{weka:3},tag:'weka',lv:2,st:'live',page:'topics/w-dpdk/index.html',steps:7,prev:['w-user','w-nm'],next:['rdma','w-op','w-comp'],d:['NeuralMesh 后端数据网络使用 DPDK，客户端可选独占核轮询、共享核 DPDK 或内核 UDP。','NeuralMesh uses DPDK for backend data networking. Clients can use dedicated-core polling, shared-core DPDK, or kernel UDP.'],kw:['独占核与共享核','Dedicated or Shared Cores','NeuralMesh 的独占核与共享核','Dedicated and Shared Cores in NeuralMesh']},

